macro_rules! deps {
    () => {
        DecodeEntry!();
        Offset!();
        Entry!();
        Error!();
        Never!();
        Location!();
    };
}

macro_rules! Find {
    () => {
        deps!();
        # [doc = " Describe how object can be located in an object store with built-in facilities to supports packs specifically."] # [doc = ""] # [doc = " ## Notes"] # [doc = ""] # [doc = " Find effectively needs [generic associated types][issue] to allow a trait for the returned object type."] # [doc = " Until then, we will have to make due with explicit types and give them the potentially added features we want."] # [doc = ""] # [doc = " Furthermore, despite this trait being in `gix-pack`, it leaks knowledge about objects potentially not being packed."] # [doc = " This is a necessary trade-off to allow this trait to live in `gix-pack` where it is used in functions to create a pack."] # [doc = ""] # [doc = " [issue]: https://github.com/rust-lang/rust/issues/44265"] pub trait Find { # [doc = " Returns true if the object exists in the database."] fn contains (& self , id : & gix_hash :: oid) -> bool ; # [doc = " Find an object matching `id` in the database while placing its raw, decoded data into `buffer`."] # [doc = " A `pack_cache` can be used to speed up subsequent lookups, set it to [`crate::cache::Never`] if the"] # [doc = " workload isn't suitable for caching."] # [doc = ""] # [doc = " Returns `Some((<object data>, <pack location if packed>))` if it was present in the database,"] # [doc = " or the error that occurred during lookup or object retrieval."] fn try_find < 'a > (& self , id : & gix_hash :: oid , buffer : & 'a mut Vec < u8 > ,) -> Result < Option < (gix_object :: Data < 'a > , Option < data :: entry :: Location >) > , gix_object :: find :: Error > { self . try_find_cached (id , buffer , & mut crate :: cache :: Never) } # [doc = " Like [`Find::try_find()`], but with support for controlling the pack cache."] # [doc = " A `pack_cache` can be used to speed up subsequent lookups, set it to [`crate::cache::Never`] if the"] # [doc = " workload isn't suitable for caching."] # [doc = ""] # [doc = " Returns `Some((<object data>, <pack location if packed>))` if it was present in the database,"] # [doc = " or the error that occurred during lookup or object retrieval."] fn try_find_cached < 'a > (& self , id : & gix_hash :: oid , buffer : & 'a mut Vec < u8 > , pack_cache : & mut dyn crate :: cache :: DecodeEntry ,) -> Result < Option < (gix_object :: Data < 'a > , Option < data :: entry :: Location >) > , gix_object :: find :: Error > ; # [doc = " Find the packs location where an object with `id` can be found in the database, or `None` if there is no pack"] # [doc = " holding the object."] # [doc = ""] # [doc = " _Note_ that this is always None if the object isn't packed even though it exists as loose object."] fn location_by_oid (& self , id : & gix_hash :: oid , buf : & mut Vec < u8 >) -> Option < data :: entry :: Location > ; # [doc = " Obtain a vector of all offsets, in index order, along with their object id."] fn pack_offsets_and_oid (& self , pack_id : u32) -> Option < Vec < (data :: Offset , gix_hash :: ObjectId) > > ; # [doc = " Return the [`find::Entry`] for `location` if it is backed by a pack."] # [doc = ""] # [doc = " Note that this is only in the interest of avoiding duplicate work during pack generation."] # [doc = " Pack locations can be obtained from [`Find::try_find()`]."] # [doc = ""] # [doc = " # Notes"] # [doc = ""] # [doc = " Custom implementations might be interested in providing their own meta-data with `object`,"] # [doc = " which currently isn't possible as the `Locate` trait requires GATs to work like that."] fn entry_by_location (& self , location : & data :: entry :: Location) -> Option < find :: Entry > ; }
    };
}

Find!()